using System.Collections.Frozen;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
namespace CombatSolver;
// RESEARCH ONLY: positive source-type scope, not a callback/event/future safety certificate.
internal static class TaskExhaustSourceScope
{
    private static readonly FrozenSet<Type> Sources = new Type[] {typeof(global::MegaCrit.Sts2.Core.Models.Cards.AscendersBane),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Backstab),typeof(global::MegaCrit.Sts2.Core.Models.Cards.BladeOfInk),typeof(global::MegaCrit.Sts2.Core.Models.Cards.BubbleBubble),typeof(global::MegaCrit.Sts2.Core.Models.Cards.DefendSilent),typeof(global::MegaCrit.Sts2.Core.Models.Cards.FanOfKnives),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Flechettes),typeof(global::MegaCrit.Sts2.Core.Models.Cards.FranticEscape),typeof(global::MegaCrit.Sts2.Core.Models.Cards.MasterPlanner),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Neutralize),typeof(global::MegaCrit.Sts2.Core.Models.Cards.NoxiousFumes),typeof(global::MegaCrit.Sts2.Core.Models.Cards.PreciseCut),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Prepared),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Prowess),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Reflex),typeof(global::MegaCrit.Sts2.Core.Models.Cards.RollingBoulder),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Shiv),typeof(global::MegaCrit.Sts2.Core.Models.Cards.StrikeSilent),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Survivor),typeof(global::MegaCrit.Sts2.Core.Models.Cards.TheHunt),typeof(global::MegaCrit.Sts2.Core.Models.Enchantments.Inky),typeof(global::MegaCrit.Sts2.Core.Models.Monsters.TheInsatiable),typeof(global::MegaCrit.Sts2.Core.Models.Potions.Fortifier),typeof(global::MegaCrit.Sts2.Core.Models.Potions.LuckyTonic),typeof(global::MegaCrit.Sts2.Core.Models.Powers.AccelerantPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.BufferPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.CrueltyPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.DebilitatePower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.DexterityPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.FanOfKnivesPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.MasterPlannerPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.NoxiousFumesPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.PoisonPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.RollingBoulderPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.SandpitPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.StrengthPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.TheHuntPower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.VulnerablePower),typeof(global::MegaCrit.Sts2.Core.Models.Powers.WeakPower),typeof(global::MegaCrit.Sts2.Core.Models.Relics.BowlerHat),typeof(global::MegaCrit.Sts2.Core.Models.Relics.FestivePopper),typeof(global::MegaCrit.Sts2.Core.Models.Relics.PaperKrane),typeof(global::MegaCrit.Sts2.Core.Models.Relics.PaperPhrog),typeof(global::MegaCrit.Sts2.Core.Models.Relics.RingOfTheSnake),typeof(global::MegaCrit.Sts2.Core.Models.Relics.SparklingRouge),typeof(global::MegaCrit.Sts2.Core.Models.Badges.CccComboModel),typeof(global::MegaCrit.Sts2.Core.Models.Badges.DebufferModel),typeof(global::MegaCrit.Sts2.Core.Models.Singleton.MultiplayerScalingModel)} .ToFrozenSet();
    private static readonly FrozenSet<Type> Cards = new Type[] {typeof(global::MegaCrit.Sts2.Core.Models.Cards.AscendersBane),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Backstab),typeof(global::MegaCrit.Sts2.Core.Models.Cards.BladeOfInk),typeof(global::MegaCrit.Sts2.Core.Models.Cards.BubbleBubble),typeof(global::MegaCrit.Sts2.Core.Models.Cards.DefendSilent),typeof(global::MegaCrit.Sts2.Core.Models.Cards.FanOfKnives),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Flechettes),typeof(global::MegaCrit.Sts2.Core.Models.Cards.FranticEscape),typeof(global::MegaCrit.Sts2.Core.Models.Cards.MasterPlanner),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Neutralize),typeof(global::MegaCrit.Sts2.Core.Models.Cards.NoxiousFumes),typeof(global::MegaCrit.Sts2.Core.Models.Cards.PreciseCut),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Prepared),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Prowess),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Reflex),typeof(global::MegaCrit.Sts2.Core.Models.Cards.RollingBoulder),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Shiv),typeof(global::MegaCrit.Sts2.Core.Models.Cards.StrikeSilent),typeof(global::MegaCrit.Sts2.Core.Models.Cards.Survivor),typeof(global::MegaCrit.Sts2.Core.Models.Cards.TheHunt)} .ToFrozenSet();
    internal static bool Capture(CombatPredictionSimulator simulator, Player player)
    {
        var combat=(SimulatedCombatState)simulator.State.CombatState;
        if(typeof(CardModel).Module.ModuleVersionId!=new Guid("8a76776c-0ce1-4d4f-90bd-8cce653dad8e")
            ||combat.TaskHasRootFloatingSources||combat.Players.Count!=1||combat.Modifiers.Count!=0||combat.RootRunModSubscriberCount!=0
            ||combat.RootCombatModSubscriberCount!=0||combat.RootHasBaseLibCardModifiers||combat.AdaptedOnPlay is not null
            ||simulator.State.GetPlayerCombatState(player).OrbQueue.Orbs.Count!=0)return false;
        if(combat.FirstRejectedHealingRootSource(static source=>Sources.Contains(source.GetType())) is not null)return false;
        return simulator.State.GetPlayerCombatState(player).AllCards.Concat(combat.PendingReturningCards)
            .All(static card=>Cards.Contains(card.Preview.GetType())&&card.Preview.Affliction is null
                &&(card.Preview.Enchantment is null||card.Preview.Enchantment.GetType()==typeof(global::MegaCrit.Sts2.Core.Models.Enchantments.Inky)));
    }
    internal static bool CurrentScope(CombatPredictionSimulator simulator, Player player)
    {
        var combat=(SimulatedCombatState)simulator.State.CombatState;
        if(simulator.HasPendingChoice)return false;
        foreach(var card in simulator.State.GetPlayerCombatState(player).AllCards.Concat(combat.PendingReturningCards))
            if(!Cards.Contains(card.Preview.GetType())||card.Preview.Affliction is not null
                ||card.Preview.Enchantment is not null&&card.Preview.Enchantment.GetType()!=typeof(global::MegaCrit.Sts2.Core.Models.Enchantments.Inky))return false;
        foreach(var power in combat.EffectivePowers())if(!Sources.Contains(power.GetType()))return false;
        foreach(var relic in combat.RelicsOf(player))if(!Sources.Contains(relic.GetType()))return false;
        foreach(var enemy in combat.KnownEnemies)if(enemy.Monster is not null&&!Sources.Contains(enemy.Monster.GetType()))return false;
        int slots=((ICombatPredictionPlayerLimits)combat).GetPotionSlotCount(player);
        for(int slot=0;slot<slots;slot++)if(combat.GetPotionAtSlot(player,slot) is { } potion&&!Sources.Contains(potion.GetType()))return false;
        return true;
    }
    internal static bool Eligible(PredictedCard card)=>Cards.Contains(card.Preview.GetType())
        &&card.Preview.Enchantment is null&&card.Preview.Affliction is null;
}
internal sealed partial class CombatBeamSolver
{
    private bool TaskHasExhaustOrderOpportunity(SimCardPile pile)
    {
        Type? first=null;
        foreach(PredictedCard card in pile.Cards)
        {
            if(!TaskExhaustSourceScope.Eligible(card))continue;
            Type type=card.Preview.GetType();
            if(first is not null&&first!=type)return true;
            first=type;
        }
        return false;
    }
    private void TaskAppendPartialExhaustKey(ref StateFingerprintBuilder key, SimCardPile pile)
    {
        PredictedCard[] sorted=pile.Cards.Select((card,index)=>(Card:card,Index:index,Type:card.Preview.GetType().FullName))
            .Where(static item=>TaskExhaustSourceScope.Eligible(item.Card))
            .OrderBy(static item=>item.Type,StringComparer.Ordinal).ThenBy(static item=>item.Index)
            .Select(static item=>item.Card).ToArray();
        int next=0;StateFingerprintBuilder pileKey=new();pileKey.Add(pile.Cards.Count);
        foreach(PredictedCard card in pile.Cards)
        {
            StateFingerprint value=BuildCardStateFingerprint(TaskExhaustSourceScope.Eligible(card)?sorted[next++]:card);
            pileKey.Add(value.First);pileKey.Add(value.Second);
        }
        StateFingerprint result=pileKey.Finish();key.Add('X');key.Add(pile.Cards.Count);key.Add(result.First);key.Add(result.Second);
